import{_ as s,C as o,o as e,c as h,j as i,a as t,E as l,a2 as n}from"./chunks/framework.C21TwvGF.js";const j=JSON.parse(`{"title":"10-dars (Mentor). Shrift (tipografiya) va uning UX dizaynga ta'siri","description":"","frontmatter":{"title":"10-dars (Mentor). Shrift (tipografiya) va uning UX dizaynga ta'siri","layout":"doc","sidebar":false,"aside":false,"outline":false,"kind":"mentor_dars","dars":{"sinf":{"name":"9-sinf (UX/UI)","link":"/mentor/9-sinf/"},"week":{"n":4,"link":"/mentor/9-sinf/hafta-04/"},"g":10,"title":"Shrift (tipografiya) va uning UX dizaynga ta'siri","lead":"Chiroyli rasm va tugmalar bo'lsa-yu, matnni o'qib bo'lmasa, ilovadan kim foydalanadi? Ushbu darsda interfeysning \\"ovoz ohangi\\" hisoblangan tipografiya, shrift turlari va ularni Figma'da sozlashni o'rganamiz.","slide":"/slaydlar/9-sinf/hafta-04/dars-1.html","test":"/slaydlar/9-sinf/hafta-04/dars-1-test.html","student_link":"/9-sinf/hafta-04/dars-1","tabs":[{"g":10,"link":"/mentor/9-sinf/hafta-04/dars-1","current":true},{"g":11,"link":"/mentor/9-sinf/hafta-04/dars-2","current":false},{"g":12,"link":"/mentor/9-sinf/hafta-04/dars-3","current":false}],"prev":null,"next":{"g":11,"title":"UI elementlarida rang nazariyasi","link":"/mentor/9-sinf/hafta-04/dars-2"}}},"headers":[],"relativePath":"mentor/9-sinf/hafta-04/dars-1.md","filePath":"mentor/9-sinf/hafta-04/dars-1.md"}`),d={name:"mentor/9-sinf/hafta-04/dars-1.md"},m={class:"blk"},g={id:"_1-dars-rejasi",tabindex:"-1"},u={class:"blk"},f={id:"_2-dars-konspekti",tabindex:"-1"},y={class:"blk"},b={id:"_3-amaliy-mashg-ulot",tabindex:"-1"},k={class:"blk"},p={id:"_4-tezkor-nazorat-4-savol",tabindex:"-1"},v={class:"blk"},c={id:"_5-mentor-uchun-izoh",tabindex:"-1"};function q(_,a,z,S,x,T){const r=o("Icon");return e(),h("div",null,[a[15]||(a[15]=i("p",null,[i("strong",null,"Hafta:"),t(" 4 · "),i("strong",null,"Davomiyligi:"),t(" 80 daqiqa · "),i("strong",null,"Turi:"),t(" nazariya + dizayn amaliyoti (Figma) · "),i("strong",null,"I-bob"),t(", 1.4-mavzu, 1-dars")],-1)),i("div",m,[i("h2",g,[l(r,{name:"file-text"}),a[0]||(a[0]=t(" 1. Dars rejasi ",-1)),a[1]||(a[1]=i("a",{class:"header-anchor",href:"#_1-dars-rejasi","aria-label":'Permalink to "<Icon name="file-text" /> 1. Dars rejasi"'},"​",-1))]),a[2]||(a[2]=n('<p><strong>Maqsad:</strong> o&#39;quvchilar tipografiya tushunchasini, shrift (typeface) va shrift turi (font) farqini, shriftning 4 asosiy jihatini va 4 asosiy shrift turini (Serif, Sans Serif, dekorativ, skript) o&#39;rganadi; Figma dasturining Typography bo&#39;limida shrift oilasi, uslubi va o&#39;lchamini sozlaydi.</p><p><strong>Kutiladigan natija:</strong></p><ul><li>Tipografiya ta&#39;rifini aytadi, typeface va font farqini misol bilan tushuntiradi.</li><li>Shriftning muhimligini 3 sabab (brendlash, qulaylik, inklyuzivlik) bilan izohlaydi.</li><li>Shriftning 4 jihatini (oila, o&#39;lcham, qalinlik, interval) sanaydi.</li><li>Serif va Sans Serif shriftlarni ajratadi, vaziyatga qarab tanlaydi.</li><li>Figmada «E-kutubxona» sarlavhasi uchun shrift oilasi, uslubi va o&#39;lchamini belgilaydi.</li></ul><table tabindex="0"><thead><tr><th>Vaqt</th><th>Bosqich</th><th>Mazmun</th></tr></thead><tbody><tr><td>0–10 daq</td><td>Takrorlash va kirish</td><td>3-hafta: wireframe va Figmaga eksport. Savol: «Wireframe kulrang edi, UI dizaynda birinchi nima qo&#39;shiladi?» (ranglar, shriftlar). Ikki telefon ekrani misoli</td></tr><tr><td>10–35 daq</td><td>Yangi mavzu</td><td>Tipografiya, typeface va font, shriftning 4 jihati, shrift turlari, tanlash tavsiyalari</td></tr><tr><td>35–40 daq</td><td>Tanaffus</td><td>Harakatli tanaffus</td></tr><tr><td>40–70 daq</td><td>Amaliy mashg&#39;ulot</td><td>Figmada Typography bo&#39;limi: oila, uslub, o&#39;lcham</td></tr><tr><td>70–76 daq</td><td>Tezkor nazorat</td><td>4 ta savol</td></tr><tr><td>76–80 daq</td><td>Xulosa va uyga vazifa</td><td>Uyga vazifani tushuntirish</td></tr></tbody></table><p><strong>Vositalar:</strong> kompyuter yoki noutbuk (internetga ulangan), Figma (figma.com, bepul hisob; o&#39;rnatish shart emas, brauzerda ishlaydi). Mentorga: o&#39;quvchilarda Figma hisobi oldindan ochilganini tekshiring.</p><hr>',6))]),i("div",u,[i("h2",f,[l(r,{name:"file-text"}),a[3]||(a[3]=t(" 2. Dars konspekti ",-1)),a[4]||(a[4]=i("a",{class:"header-anchor",href:"#_2-dars-konspekti","aria-label":'Permalink to "<Icon name="file-text" /> 2. Dars konspekti"'},"​",-1))]),a[5]||(a[5]=n('<h3 id="_2-1-tipografiya-nima" tabindex="-1">2.1. Tipografiya nima? <a class="header-anchor" href="#_2-1-tipografiya-nima" aria-label="Permalink to &quot;2.1. Tipografiya nima?&quot;">​</a></h3><p>Tipografiya (shrift) – bu foydalanuvchi interfeysi tarkibini tanib olinadigan, o&#39;qilishi mumkin bo&#39;lgan va vizual tarzda jalb qiladigan tarzda harflar va matnlarni tartibga solish amaliyotidir.</p><p>O&#39;xshatish: tipografiya matnning «ovoz ohangi» kabi. Bir xil gapni baqirib ham, pichirlab ham aytish mumkin. Shrift ham gapning ohangini belgilaydi.</p><h3 id="_2-2-shrift-typeface-va-shrift-turi-font" tabindex="-1">2.2. Shrift (typeface) va shrift turi (font) <a class="header-anchor" href="#_2-2-shrift-typeface-va-shrift-turi-font" aria-label="Permalink to &quot;2.2. Shrift (typeface) va shrift turi (font)&quot;">​</a></h3><p>Bu ikki atama ko&#39;pincha bir-birining o&#39;rnida ishlatiladi, lekin farq bor:</p><ul><li><strong>Shrift (typeface)</strong> – bir xil dizayn uslubiga ega shriftlarning butun oilasi.</li><li><strong>Shrift turi (font)</strong> – shu oila ichidagi og&#39;irlik (weight), kenglik (width) va uslub (style) kabi o&#39;zgarishlar.</li></ul><p>Misol: <em>Times New Roman</em> – typeface. <em>Times New Roman Bold Italic</em> – uning fonti.</p><h3 id="_2-3-shrift-nega-muhim" tabindex="-1">2.3. Shrift nega muhim? <a class="header-anchor" href="#_2-3-shrift-nega-muhim" aria-label="Permalink to &quot;2.3. Shrift nega muhim?&quot;">​</a></h3><ol><li><strong>Brendlash:</strong> shriftlar kompaniyaning ovozi va uslubini mustahkamlaydi; yagona shriftdan foydalanish ishonch va barqarorlik yaratadi.</li><li><strong>Foydalanish qulayligi (usability):</strong> o&#39;qilishi oson, kontrasti to&#39;g&#39;ri shrift ma&#39;lumotni tez anglashga yordam beradi.</li><li><strong>Inklyuzivlik (accessibility):</strong> ko&#39;rish qobiliyati cheklanganlar uchun ham qulay tipografiya tanlash.</li></ol><h3 id="_2-4-shriftning-asosiy-jihatlari" tabindex="-1">2.4. Shriftning asosiy jihatlari <a class="header-anchor" href="#_2-4-shriftning-asosiy-jihatlari" aria-label="Permalink to &quot;2.4. Shriftning asosiy jihatlari&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Jihat</th><th>Mazmuni</th></tr></thead><tbody><tr><td>Shrift oilasi (font family)</td><td>serif, sans-serif, display, monospace</td></tr><tr><td>Shrift o&#39;lchami (font size)</td><td>mobil qurilmalarda o&#39;qish uchun qulay minimal o&#39;lcham 14–16 pt</td></tr><tr><td>Qalinlik (font weight)</td><td>muhim matn 600–700, oddiy matn 400</td></tr><tr><td>Interval (line spacing, letter spacing)</td><td>o&#39;qishni yengillashtiradi</td></tr></tbody></table><p>Eslatma: o&#39;qo&#39;v qo&#39;llanma o&#39;lchamni «pt» da beradi, Figmada esa o&#39;lcham «px» kiritiladi. Darsda ikkalasini aralashtirmang: bu hujjatdagi raqam, Figmada esa 24 px misol bor.</p><h3 id="_2-5-to-rt-asosiy-shrift-turi" tabindex="-1">2.5. To&#39;rt asosiy shrift turi <a class="header-anchor" href="#_2-5-to-rt-asosiy-shrift-turi" aria-label="Permalink to &quot;2.5. To&#39;rt asosiy shrift turi&quot;">​</a></h3><ul><li><strong>Serif</strong> – kitoblar, gazetalar, jurnallarda ishlatiladigan klassik shriftlar; adabiylik, yuqori saviya, ishonchlilik. Masalan: Times New Roman, Merriweather.</li><li><strong>Sans Serif</strong> – zamonaviy, toza, minimal; veb-sayt va mobil ilovalarda; soddalik, neytrallik. Masalan: Arial, Roboto.</li><li><strong>Dekorativ</strong> – logotip va sarlavhalarda; kayfiyat yoki brend uslubini beradi, o&#39;qilishdan ko&#39;ra estetikaga urg&#39;u. Masalan: Cooper Black, Lobster.</li><li><strong>Skript</strong> – qo&#39;l yozuviga o&#39;xshash. Tasodifiy skript – shaxsiylik, samimiylik; rasmiy skript – nafislik, rasmiylik. Masalan: Pacifico, Caveat.</li></ul><p>Google Fonts kabi saytlarda kontent turli shriftlarda qanday ko&#39;rinishini ko&#39;rish mumkin.</p><h3 id="_2-6-tipografiya-tanlash-bo-yicha-tavsiyalar" tabindex="-1">2.6. Tipografiya tanlash bo&#39;yicha tavsiyalar <a class="header-anchor" href="#_2-6-tipografiya-tanlash-bo-yicha-tavsiyalar" aria-label="Permalink to &quot;2.6. Tipografiya tanlash bo&#39;yicha tavsiyalar&quot;">​</a></h3><ol><li><strong>Brendni aks ettiruvchi shriftni tanlang.</strong> Jekob qonuniga (Jakob&#39;s Law) rioya qiling: foydalanuvchilarning o&#39;xshash saytlarda shakllangan kutishlariga mos shrift tanlang.</li><li><strong>Sukut bo&#39;yicha sans serif.</strong> Bolalar, keksalar, ko&#39;rish qobiliyati past va disleksiyali foydalanuvchilar uchun sans serif o&#39;qish va skanerlash qulayroq.</li><li><strong>«Shakl funksiyadan keyin» (Form follows function).</strong> GOV.UK sans serif ishlatadi (foydalanuvchilar tez xizmat olib chiqib ketishni xohlaydi), The Atlantic serif ishlatadi (uzoq o&#39;qish va fikr yuritish uchun).</li><li><strong>Tipografiyani foydalanuvchilar bilan sinang:</strong> maqsadga muvofiqlik testlari, fokus-guruhlar, A/B testlar, ko&#39;zni kuzatish.</li><li><strong>Foydalanuvchiga moslashtirish imkoni berish:</strong> matn hajmini o&#39;zgartirish, kontrast, yordamchi texnologiyalar, disleksiyali o&#39;quvchilar uchun Dyslexie kabi maxsus shriftlar.</li></ol><h3 id="_2-7-figma-amaliyoti-typography-uslubiy-ko-rsatma-bo-yicha" tabindex="-1">2.7. Figma amaliyoti: Typography (uslubiy ko&#39;rsatma bo&#39;yicha) <a class="header-anchor" href="#_2-7-figma-amaliyoti-typography-uslubiy-ko-rsatma-bo-yicha" aria-label="Permalink to &quot;2.7. Figma amaliyoti: Typography (uslubiy ko&#39;rsatma bo&#39;yicha)&quot;">​</a></h3><p>Shrift (typography) matnlarning o&#39;qilishi va vizual ierarxiyasini belgilaydi. Sarlavhalar, bo&#39;lim nomlari va asosiy matn uchun shrift o&#39;lchami va qalinligi turlicha bo&#39;lishi lozim.</p><ol><li>Text elementini tanlang. O&#39;ng tomondagi <strong>Typography</strong> bo&#39;limida shrift sozlamalari ochiladi.</li><li>Shriftlar ro&#39;yxatidan <strong>Inria Serif</strong> tanlanadi: sarlavha va bo&#39;lim nomlarini ajratish uchun mos; serif shriftlar dizaynga rasmiylik va aniqlik beradi.</li><li>Uslub (Style) ro&#39;yxatida Light, Regular, Bold, Italic, Bold Italic bor. Misolda <strong>Bold Italic</strong> tanlangan. Bold/Bold Italic muhim bo&#39;lim nomlari uchun, Regular oddiy matn uchun.</li><li>Shrift o&#39;lchami (font size): matnga <strong>24 px</strong> beriladi. Sarlavha katta, oddiy matn kichik: shunda aniq vizual ierarxiya hosil bo&#39;ladi.</li></ol><hr>',21))]),i("div",y,[i("h2",b,[l(r,{name:"file-text"}),a[6]||(a[6]=t(" 3. Amaliy mashg'ulot ",-1)),a[7]||(a[7]=i("a",{class:"header-anchor",href:"#_3-amaliy-mashg-ulot","aria-label":`Permalink to "<Icon name="file-text" /> 3. Amaliy mashg'ulot"`},"​",-1))]),a[8]||(a[8]=n('<p>Umumiy shart: Figmada «E-kutubxona» mavzusida ishlang (3-haftada wireframe qilingan loyiha). Natija: skrinshot.</p><h3 id="_1-mashq-sarlavhaga-shrift-berish-·-oson" tabindex="-1">1-mashq. Sarlavhaga shrift berish · oson <a class="header-anchor" href="#_1-mashq-sarlavhaga-shrift-berish-·-oson" aria-label="Permalink to &quot;1-mashq. Sarlavhaga shrift berish · oson&quot;">​</a></h3><p><strong>Vazifa:</strong> Figmada yangi Frame oching, «E-kutubxona» matnini yozing va Typography bo&#39;limida Inria Serif, Bold, 24 px belgilang.</p><p><strong>Yechim:</strong></p><ol><li><code>F</code> tugmasi bilan Frame (masalan, Desktop) oching.</li><li><code>T</code> tugmasi bilan matn yozing: «E-kutubxona».</li><li>O&#39;ng panel → Typography: font family = Inria Serif; Style = Bold; Size = 24.</li><li>Skrinshot oling.</li></ol><h3 id="_2-mashq-matn-ierarxiyasi-·-o-rta" tabindex="-1">2-mashq. Matn ierarxiyasi · o&#39;rta <a class="header-anchor" href="#_2-mashq-matn-ierarxiyasi-·-o-rta" aria-label="Permalink to &quot;2-mashq. Matn ierarxiyasi · o&#39;rta&quot;">​</a></h3><p><strong>Vazifa:</strong> Bitta ekranda 3 daraja matn yarating: sarlavha, bo&#39;lim nomi, oddiy matn. Har biriga turli o&#39;lcham va qalinlik bering.</p><p><strong>Yechim:</strong> namuna (o&#39;quvchi boshqa qiymat tanlashi mumkin, asosiysi: o&#39;lcham va qalinlik pasayib boradi):</p><ul><li>Sarlavha: Inria Serif, Bold, 32 px.</li><li>Bo&#39;lim nomi («Yangi kitoblar»): Inria Serif, Bold Italic, 24 px.</li><li>Oddiy matn: Sans Serif (masalan, Roboto), Regular (400), 16 px. Tekshirish: ko&#39;z avval sarlavhaga tushadi. Agar uchalasi bir xil bo&#39;lsa, ierarxiya yo&#39;q.</li></ul><h3 id="_3-mashq-serif-yoki-sans-serif-·-qiyin" tabindex="-1">3-mashq. Serif yoki Sans Serif? · qiyin <a class="header-anchor" href="#_3-mashq-serif-yoki-sans-serif-·-qiyin" aria-label="Permalink to &quot;3-mashq. Serif yoki Sans Serif? · qiyin&quot;">​</a></h3><p><strong>Vazifa:</strong> Bir xil kitob tavsifini ikki xil shrift juftligida (hammasi serif va hammasi sans serif) yasang. Qaysi biri mobilda o&#39;qishga qulayroq? Sababini 2 jumlada yozing.</p><p><strong>Yechim:</strong> o&#39;quvchi fikri bo&#39;lishi mumkin, lekin hujjat bo&#39;yicha asos: serif klassik va rasmiy (uzoq o&#39;qish, jurnal), sans serif esa veb va mobil ilovada aniq, sodda, skanerlash oson (bolalar, keksalar, disleksiyali foydalanuvchilar uchun ham qulay). Shuning uchun sukut bo&#39;yicha sans serif tavsiya etiladi. Sarlavhada serif ishlatsa bo&#39;ladi.</p><hr>',13))]),i("div",k,[i("h2",p,[l(r,{name:"file-text"}),a[9]||(a[9]=t(" 4. Tezkor nazorat (4 savol) ",-1)),a[10]||(a[10]=i("a",{class:"header-anchor",href:"#_4-tezkor-nazorat-4-savol","aria-label":'Permalink to "<Icon name="file-text" /> 4. Tezkor nazorat (4 savol)"'},"​",-1))]),a[11]||(a[11]=n("<ol><li>Typeface va font farqi nima? <ul><li><strong>Javob:</strong> typeface – shriftlarning butun oilasi (Times New Roman); font – oila ichidagi variant (Bold Italic).</li></ul></li><li>Shriftning 4 asosiy jihatini sanang. <ul><li><strong>Javob:</strong> oila, o&#39;lcham, qalinlik, interval (line/letter spacing).</li></ul></li><li>Serif va Sans Serif farqi nima, har biri qayerda qo&#39;llanadi? <ul><li><strong>Javob:</strong> Serif – kitob, gazeta, jurnal (klassik); Sans Serif – veb-sayt va mobil ilova (toza, zamonaviy).</li></ul></li><li>Figmada shrift sozlamalari qayerda? <ul><li><strong>Javob:</strong> Text elementini tanlagach, o&#39;ng paneldagi Typography bo&#39;limida.</li></ul></li></ol>",1))]),i("div",v,[i("h2",c,[l(r,{name:"file-text"}),a[12]||(a[12]=t(" 5. Mentor uchun izoh ",-1)),a[13]||(a[13]=i("a",{class:"header-anchor",href:"#_5-mentor-uchun-izoh","aria-label":'Permalink to "<Icon name="file-text" /> 5. Mentor uchun izoh"'},"​",-1))]),a[14]||(a[14]=i("ul",null,[i("li",null,"Vaqtni bo'lib boring: nazariya uzoq cho'zilib ketmasin, asosiy ish Figmada."),i("li",null,"Hujjatdagi aniq raqamlar: 14–16 pt (mobil), 400 va 600–700 (qalinlik), 24 px (Figma misoli), Inria Serif."),i("li",null,"Dekorativ va skript shriftlarni uzun matnga ishlatmaslikni ta'kidlang (bu hujjat xulosasi: dekorativ shriftlar o'qilishdan ko'ra estetikaga urg'u beradi).")],-1))])])}const P=s(d,[["render",q]]);export{j as __pageData,P as default};
